// RANGO (no condition): retirable el valor actual si NO hay cuenta viva de su IIA en el contexto.
if (input == null || basic.stringify(input).trim() == '') return false
def CANARIO = ['202014210', '202622500', '201610032', '201122601', '202514113', '202622704', '201811473', '45302782']  // vacio = todos; con nombres = SOLO esos usuarios (encendido acotado)
if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
try { def gone = !midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e22'); if (gone) log.warn('R1v2: retira {} de {} (sin cuenta viva de su IIA)', input, focus?.name); return gone } catch (Exception e) { log.warn('R1v2: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }

