if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
try { def gone = !midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e23'); if (gone) log.warn('R2v2: retira {} de {} (sin cuenta viva de su IIA)', input, focus?.name); return gone } catch (Exception e) { log.warn('R2v2: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }

