try { def gone = !midpoint.hasLinkedAccount('6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e21'); if (gone) log.warn('R3v2: retira {} de {} (sin cuenta viva de su IIA)', input, focus?.name); return gone } catch (Exception e) { log.warn('R3v2: hasLinkedAccount fallo en {}: {} -> no se retira', focus?.name, e.message); return false }

// RANGO (no condition): retirable el DISABLED actual si hay un vinculo VIVO (item + cuenta de su IIA).
if (input == null || !basic.stringify(input).trim().equalsIgnoreCase('disabled')) return false
def CANARIO = ['202014210', '202622500', '201610032', '201122601', '202514113', '202622704', '201811473', '45302782']  // vacio = todos; con nombres = SOLO esos usuarios (encendido acotado)
if (!CANARIO.isEmpty() && !(basic.stringify(focus?.name) in CANARIO)) return false
def NS = 'urn:sciback:midpoint:person'
def live = { String item, String res -> def v = basic.getExtensionPropertyValue(focus, NS, item); v != null && basic.stringify(v).trim() != '' && midpoint.hasLinkedAccount(res) }
try { def ok = live('liveAffiliationWorker', '6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e21') || live('liveAffiliationStudent', '6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e22') || live('liveAffiliationAlum', '6a91f7e1-1b50-4dcf-9c4b-7c0c0e0e0e23'); if (ok) log.warn('ACTv2: limpia DISABLED de {} (vinculo vivo)', focus?.name); return ok } catch (Exception e) { log.warn('ACTv2: fallo en {}: {} -> no se limpia', focus?.name, e.message); return false }

